// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, type(uint96).max);
        vm.deal(address(c), type(uint96).max);
        uint256 before = address(this).balance;
        vm.prank(address(this));
        c.withdraw(amount);
        assertEq(address(this).balance - before, amount, "withdraw must credit the caller with the exact amount");
    }
}
